package com.example.billing;

import java.time.format.DateTimeFormatter;
import org.springframework.stereotype.Service;

@Service
public class ReceiptService {

    private static final DateTimeFormatter DATE = DateTimeFormatter.ISO_LOCAL_DATE;

    private final InvoiceRepository invoices;

    public ReceiptService(InvoiceRepository invoices) {
        this.invoices = invoices;
    }

    /**
     * Marks an invoice paid outside the platform (a bank transfer reconciled
     * by hand). No Payment is recorded for it.
     */
    public void markPaidExternally(String invoiceId) {
        Invoice invoice = invoices.findById(invoiceId)
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));
        invoice.setStatus(InvoiceStatus.PAID);
        invoices.save(invoice);
    }

    public Receipt receiptFor(String invoiceId) {
        Invoice invoice = invoices.findById(invoiceId)
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));
        if (invoice.getStatus() != InvoiceStatus.PAID) {
            throw new InvoiceNotPaidException(invoiceId);
        }
        Payment payment = invoice.getPayments().get(0);
        return new Receipt(invoice.getNumber(), invoice.getTotal(),
                DATE.format(payment.getPaidAt()), payment.getMethod());
    }
}
